<?php
/** Server-rendered presentation for the team archive. */
use yii\helpers\Html;
?>
<?php $this->title = $project['title'].' · 星河工坊'; ?><a class="text-link" href="/?r=site/projects">← 返回项目探索</a><div class="page-heading"><span class="eyebrow">PROJECT DETAIL</span><h1><?= Html::encode($project['title']) ?></h1><p><?= Html::encode($project['summary']) ?></p></div><div class="detail-grid"><section class="panel prose"><h2>关于项目</h2><p><?= nl2br(Html::encode($project['description'])) ?></p><h2>项目里程碑</h2><?php foreach ($milestones as $milestone): ?><div class="milestone"><span>◉</span><div><strong><?= Html::encode($milestone['title']) ?></strong><p><?= Html::encode($milestone['due_on'] ?? $milestone['due_date'] ?? '') ?> · <?= !empty($milestone['completed']) || !empty($milestone['completed_at']) ? '已达成' : '计划中' ?></p></div></div><?php endforeach ?><?php if (!$milestones): ?><p class="muted">项目里程碑正在规划中。</p><?php endif ?></section><aside class="panel"><span class="eyebrow">THE BUILDERS</span><h2>项目伙伴</h2><?php foreach ($members as $member): ?><p><strong><?= Html::encode($member['name']) ?></strong><br><span class="muted"><?= Html::encode($member['title'] ?? '') ?></span></p><?php endforeach ?><hr><p>当前进度 <strong><?= (int)$project['progress'] ?>%</strong></p><div class="progress-track"><span style="width:<?= max(0,min(100,(int)$project['progress'])) ?>%"></span></div></aside></div><section class="section"><h2>项目动态</h2><?php foreach ($updates as $update): ?><?= $this->render('_update',compact('update')) ?><?php endforeach ?><?php if (!$updates): ?><p class="muted">暂无项目动态。</p><?php endif ?></section>
